        for c in range(len(grid[r]) - 2):
            if output[r][c] == 9 and output[r][c+1] == 9 and output[r][c+2] == 9:
                corner_rows.append((r, c, len(grid[r]) - 1 - c))  # (row, left_wall, right_wall)
                break

    # Group by left_wall (vertical channel)
    channels = {}  # left_wall -> set of (row, right_wall)
    for r, left, right in corner_rows:
        if left not in channels:
            channels[left] = [(r, right)]
        else:
